tool_sources.edge_sweep:
"""edge_sweep: stimulus that toggles control inputs right at clock edges.

Written by the Breaker coach in round 2: 7 of the 9 missed bugs only
showed up when reset or enable changed in the same cycle as a clock edge.
"""

CONTROL = ("reset", "areset", "resetn", "rst", "en", "ena", "load")


def run(spec, verilog, ports, cycles=24):
    inputs = [p for p in ports if p["dir"] == "input" and p["name"] != "clk"]
    stimulus = []
    for c in range(cycles):
        row = {}
        for i, p in enumerate(inputs):
            width = p.get("width", 1)
            mask = (1 << width) - 1
            if p["name"] in CONTROL:
                # assert on a short, irregular schedule so edges line up
                row[p["name"]] = 1 if c in (0, 5, 6, 11, 17) else 0
            elif width == 1:
                row[p["name"]] = (c >> i) & 1
            else:
                patterns = (0, mask, 0xAA & mask, 1 << (c % width))
                row[p["name"]] = patterns[(c + i) % len(patterns)]
        stimulus.append(row)
    return {
        "fired": True,
        "stimulus": stimulus,
        "findings": [f"{cycles} edge-aligned cycles over {len(inputs)} inputs"],
    }
